// src/plugin/provider/factory.ts
import { define } from "@opencode/plugin/effect/plugin";
import { Effect } from "effect";
function createProviderPlugin2(input) {
  return define({
    id: input.id,
    effect: Effect.fn(function* (ctx) {
      yield* ctx.aisdk.hook("sdk", Effect.fn(function* (evt) {
        if (evt.package !== input.package)
          return;
        evt.sdk = yield* Effect.promise(() => input.load(evt.options));
      }));
    })
  });
}

export { createProviderPlugin2 };
